function setupControls(){const pad=$('stick');if(!pad)return;const move=e=>{if(pointer!==e.pointerId)return;const rect=pad.getBoundingClientRect(),cx=rect.left+rect.width/2,cy=rect.top+rect.height/2,dx=e.clientX-cx,dy=e.clientY-cy,len=Math.max(1,Math.hypot(dx,dy)),scale=Math.min(1,len/45);stick={x:dx/len*scale,y:dy/len*scale};$('knob').style.transform='translate('+(stick.x*38)+'px,'+(stick.y*38)+'px)';};pad.onpointerdown=e=>{e.preventDefault();pointer=e.pointerId;pad.setPointerCapture(pointer);move(e);};pad.onpointermove=move;const end=e=>{if(pointer!==e.pointerId)return;pointer=null;stick={x:0,y:0};$('knob').style.transform='';};pad.onpointerup=end;pad.onpointercancel=end;}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k.startsWith('arrow'))e.preventDefault();keys.add(k);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();stick={x:0,y:0};if(run&&!run.ended)run.paused=true;});
function frame(t){const dt=Math.min(.05,(t-last)/1000||0);last=t;update(dt);draw();requestAnimationFrame(frame);}render();requestAnimationFrame(frame);
